-- down: the do block below with each seed and copy swapped (a row edited since stays as it is), then
--   update public.email_templates set variables = '{submitter_name,property_address,invoice_number,product,amount,terms,preferred_method,payment_instructions,billing_email}' where key = 'invoice';
--   update public.email_templates set variables = '{what_you_receive,market_names,latest_number,latest_title,latest_line,latest_url}' where key = 'newsletter_welcome';
set lock_timeout = '5s';

-- The email identity of 2026-10-15 (operator: "use all of the designs directions ... based on the type of the email"):
-- Threshold for the moments, Afternoon for correspondence, the light house for internal mail. Each row's copy moves to
-- the copy of its template file under src/templates/email/, which the houses draw: a row's leading level-1 headings
-- are its opening (the line that enters the door and the line that leaves it), a level-2 heading a statement, a
-- level-3 heading a label. Only a row that still holds its seed moves, so a row an admin has edited survives; the
-- revision of each change carries the note email-houses. Facts are unchanged; two variables are added from data the
-- rows already have: the invoice's issue and due dates (its frozen snapshot) and the picture of the welcome's piece.
do $$
declare
  r record;
begin
  for r in
    select * from (values
      ('received', '{"subject":"We have your submission","preheader":"We will review it and be in touch.","body":[{"type":"heading","text":"Thank you, {{submitter_name}}."},{"type":"paragraph","text":"We have received {{property_address}}, {{city}}, {{state}}. We will review it against our editorial standard and be in touch."},{"type":"paragraph","text":"Editorial consideration is free. Nothing is charged unless the property is accepted and you choose a product."},{"type":"signature"}]}'::jsonb,
       '{"subject":"{{property_address}} is with the editors","preheader":"Received, and in review. Review comes before payment.","body":[{"type":"heading","text":"{{property_address}}"},{"type":"heading","text":"is with the editors."},{"type":"paragraph","text":"Thank you for sending it to us. An editor will read it against our editorial standard, and we will be in touch."},{"type":"facts","rows":[{"label":"Submitted by","value":"{{submitter_name}}"},{"label":"The home","value":"{{property_address}}, {{city}}, {{state}}"},{"label":"Package noted","value":"{{package}}"}]},{"type":"heading","text":"How a home is chosen","level":3},{"type":"heading","text":"Review comes before payment.","level":2},{"type":"paragraph","text":"Editorial consideration is free. Nothing is charged unless the home is accepted and you choose a product."},{"type":"signature"}]}'::jsonb),
      ('declined', '{"subject":"About {{property_address}}","preheader":"","body":[{"type":"heading","text":"Thank you for submitting {{property_address}}."},{"type":"paragraph","text":"After careful reading, we will not be featuring this property at this time."},{"type":"paragraph","text":"{{reason_paragraph}}"},{"type":"paragraph","text":"{{note_paragraph}}"},{"type":"paragraph","text":"You have not been charged. You are welcome to submit another property."},{"type":"signature"}]}'::jsonb,
       '{"subject":"About {{property_address}}","preheader":"Our decision, and the reason for it.","body":[{"type":"heading","text":"{{property_address}}"},{"type":"heading","text":"after careful reading"},{"type":"paragraph","text":"Thank you for sending it to us. We will not be featuring this home at this time."},{"type":"paragraph","text":"{{reason_paragraph}}"},{"type":"paragraph","text":"{{note_paragraph}}"},{"type":"heading","text":"You have not been charged.","level":2},{"type":"paragraph","text":"You are welcome to submit another home."},{"type":"signature"}]}'::jsonb),
      ('accepted', '{"subject":"{{property_address}} has been accepted","preheader":"","body":[{"type":"heading","text":"Your property has been selected."},{"type":"paragraph","text":"We would be glad to feature {{property_address}}, {{city}}, {{state}}."},{"type":"paragraph","text":"An invoice for {{package}} will follow. Once payment is confirmed we schedule the property."},{"type":"signature"}]}'::jsonb,
       '{"subject":"{{property_address}} is accepted","preheader":"An invoice follows. We schedule the home once payment is confirmed.","body":[{"type":"heading","text":"{{property_address}}"},{"type":"heading","text":"is accepted."},{"type":"paragraph","text":"We would be glad to feature {{property_address}}, {{city}}, {{state}}."},{"type":"paragraph","text":"An invoice for {{package}} will follow. Once payment is confirmed, we schedule the home."},{"type":"heading","text":"How a home is chosen","level":3},{"type":"heading","text":"Acceptance is not for sale.","level":2},{"type":"paragraph","text":"The decision is made first, on the home alone. Payment follows it, never the other way."},{"type":"signature"}]}'::jsonb),
      ('awaiting_assets', '{"subject":"Materials for {{property_address}}","preheader":"","body":[{"type":"heading","text":"A little more, please."},{"type":"paragraph","text":"To continue with {{property_address}} we need the following."},{"type":"paragraph","text":"{{assets_note}}"},{"type":"paragraph","text":"Reply to this email with the files or a link."},{"type":"signature"}]}'::jsonb,
       '{"subject":"A little more for {{property_address}}","preheader":"To continue the review, we need a few more materials.","body":[{"type":"heading","text":"{{property_address}}"},{"type":"heading","text":"needs a little more."},{"type":"paragraph","text":"To continue with {{property_address}} we need the following."},{"type":"paragraph","text":"{{assets_note}}"},{"type":"paragraph","text":"Reply to this email with the files or a link."},{"type":"signature"}]}'::jsonb),
      ('invoice', '{"subject":"Invoice {{invoice_number}} from Matter of Place","preheader":"","body":[{"type":"heading","text":"Invoice {{invoice_number}}"},{"type":"facts","rows":[{"label":"Property","value":"{{property_address}}"},{"label":"Product","value":"{{product}}"},{"label":"Amount","value":"{{amount}}"},{"label":"Terms","value":"{{terms}}"},{"label":"Preferred payment method","value":"{{preferred_method}}"}]},{"type":"paragraph","text":"How to pay"},{"type":"paragraph","text":"{{payment_instructions}}"},{"type":"paragraph","text":"Your property is scheduled once payment is confirmed. The invoice is attached."},{"type":"paragraph","text":"Questions about this invoice: {{billing_email}}."},{"type":"signature"}]}'::jsonb,
       '{"subject":"Invoice {{invoice_number}} from Matter of Place","preheader":"{{amount}} for {{product}}, {{property_address}}. Due {{due_date}}.","body":[{"type":"heading","text":"{{product}}"},{"type":"heading","text":"for {{property_address}}"},{"type":"facts","rows":[{"label":"Issued","value":"{{issue_date}}"},{"label":"Due","value":"{{due_date}}"},{"label":"Terms","value":"{{terms}}"},{"label":"Preferred method","value":"{{preferred_method}}"}]},{"type":"heading","text":"How to pay","level":3},{"type":"paragraph","text":"{{payment_instructions}}"},{"type":"heading","text":"Your home is scheduled once payment is confirmed.","level":2},{"type":"paragraph","text":"The invoice is attached. Questions about it: {{billing_email}}."},{"type":"signature"}]}'::jsonb),
      ('inquiry_ack', '{"subject":"We have your message","preheader":"","body":[{"type":"heading","text":"Thank you, {{name}}."},{"type":"paragraph","text":"A person will reply within one working day."},{"type":"signature"}]}'::jsonb,
       '{"subject":"We have your message","preheader":"A person will reply within one working day.","body":[{"type":"heading","text":"Your message"},{"type":"heading","text":"is with us."},{"type":"paragraph","text":"Thank you, {{name}}. A person will reply within one working day."},{"type":"signature"}]}'::jsonb),
      ('inquiry_forward', '{"subject":"A message about {{property_title}}","preheader":"Sent through Matter of Place.","body":[{"type":"heading","text":"A message about {{property_title}}"},{"type":"paragraph","text":"{{inquirer_name}} wrote to you through Matter of Place:"},{"type":"paragraph","text":"{{message}}"},{"type":"paragraph","text":"You can reach them at {{inquirer_contact}}."},{"type":"paragraph","text":"Matter of Place passes the message on and does not take part in the conversation."},{"type":"signature"}]}'::jsonb,
       '{"subject":"A message about {{property_title}}","preheader":"Sent through Matter of Place.","body":[{"type":"heading","text":"A message about {{property_title}}"},{"type":"paragraph","text":"{{inquirer_name}} wrote to you through Matter of Place:"},{"type":"paragraph","text":"{{message}}"},{"type":"facts","rows":[{"label":"From","value":"{{inquirer_name}}"},{"label":"Reach them at","value":"{{inquirer_contact}}"}]},{"type":"paragraph","text":"Matter of Place passes the message on and does not take part in the conversation."},{"type":"signature"}]}'::jsonb),
      ('interest_confirm', '{"subject":"Confirm your interest in {{market_names}}","preheader":"","body":[{"type":"heading","text":"Confirm your interest."},{"type":"paragraph","text":"You asked to hear when Matter of Place publishes its first property in {{market_names}}."},{"type":"button","label":"Confirm","url":"{{confirm_url}}"},{"type":"paragraph","text":"If this was not you, ignore this email and nothing will be sent."}]}'::jsonb,
       '{"subject":"Confirm your interest in {{market_names}}","preheader":"One click confirms it.","body":[{"type":"heading","text":"One click"},{"type":"heading","text":"to confirm."},{"type":"paragraph","text":"You asked to hear when Matter of Place publishes its first home in {{market_names}}."},{"type":"button","label":"Confirm","url":"{{confirm_url}}"},{"type":"paragraph","text":"If this was not you, ignore this email and nothing will be sent."}]}'::jsonb),
      ('newsletter_confirm', '{"subject":"Confirm your Place Notes subscription","preheader":"","body":[{"type":"heading","text":"One click to confirm."},{"type":"paragraph","text":"Place Notes brings selected properties and stories from California, New York and Florida, about every two weeks."},{"type":"button","label":"Confirm","url":"{{confirm_url}}"},{"type":"paragraph","text":"If this was not you, ignore this email and nothing will be sent."}]}'::jsonb,
       '{"subject":"Confirm your Place Notes subscription","preheader":"One click confirms it.","body":[{"type":"heading","text":"One click"},{"type":"heading","text":"to confirm."},{"type":"paragraph","text":"Place Notes brings selected homes and stories from California, New York and Florida, about every two weeks."},{"type":"button","label":"Confirm","url":"{{confirm_url}}"},{"type":"paragraph","text":"If this was not you, ignore this email and nothing will be sent."}]}'::jsonb),
      ('subject_ack', '{"subject":"We have your privacy request","preheader":"We will answer by {{due_date}}.","body":[{"type":"heading","text":"We have your request."},{"type":"paragraph","text":"We received your {{kind_label}} request and will answer by {{due_date}}, within 45 days of receiving it."},{"type":"paragraph","text":"To confirm it is you, we may ask you to reply from this address."},{"type":"signature"}]}'::jsonb,
       '{"subject":"We have your privacy request","preheader":"We will answer by {{due_date}}.","body":[{"type":"heading","text":"Your {{kind_label}} request"},{"type":"heading","text":"is with us"},{"type":"paragraph","text":"We received your {{kind_label}} request and will answer by {{due_date}}, within 45 days of receiving it."},{"type":"paragraph","text":"To confirm it is you, we may ask you to reply from this address."},{"type":"signature"}]}'::jsonb),
      ('newsletter_welcome', '{"subject":"Welcome to Matter of Place","preheader":"What we will send you, and how often.","body":[{"type":"heading","text":"Thank you for confirming."},{"type":"paragraph","text":"Matter of Place publishes existing homes in California, New York and Florida, one at a time, each chosen for what it is rather than what it costs."},{"type":"paragraph","text":"{{what_you_receive}}"},{"type":"paragraph","text":"We write only when there is something to read. If you would rather not hear from us, reply to this email at any time and we will take you off the list."}]}'::jsonb,
       '{"subject":"Welcome to Matter of Place","preheader":"What we will send you, and how often.","body":[{"type":"heading","text":"The door"},{"type":"heading","text":"is open."},{"type":"paragraph","text":"Matter of Place publishes existing homes in California, New York and Florida, one at a time, each chosen for what it is rather than what it costs."},{"type":"paragraph","text":"{{what_you_receive}}"},{"type":"heading","text":"We write only when there is something to read.","level":2},{"type":"paragraph","text":"If you would rather not hear from us, reply to this email at any time and we will take you off the list."}]}'::jsonb)
    ) as t(key, seed, copy)
  loop
    if exists (
      select 1 from public.email_templates
      where key = r.key
        and subject = r.seed ->> 'subject'
        and preheader = r.seed ->> 'preheader'
        and body = r.seed -> 'body'
    ) then
      perform public.automation_put_template(r.key, r.copy, null, null, 'email-houses', 'email-houses');
    end if;
  end loop;
  perform set_config('mop.note', '', true);
end;
$$;

update public.email_templates set variables = '{submitter_name,property_address,invoice_number,product,amount,terms,preferred_method,payment_instructions,billing_email,issue_date,due_date}' where key = 'invoice';
update public.email_templates set variables = '{what_you_receive,market_names,latest_number,latest_title,latest_line,latest_url,latest_image}' where key = 'newsletter_welcome';
